import zipfile
from src.preprocess import file_sha256
_pfolder = ROOT / 'models/P_darijabert_without_both_s42'
_expected = json.loads((_pfolder / 'artifact_sha256.json').read_text())['weights.pt']
print('SHA256 attendu :', _expected)
for _p in [_pfolder / 'weights.pt', Path('/content/P_weights.pt')]:
    if _p.is_file():
        print('FICHIER', str(_p), 'OCTETS', _p.stat().st_size, 'SHA256', file_sha256(_p), 'ZIP', zipfile.is_zipfile(_p), flush=True)
    else:
        print('ABSENT', str(_p), flush=True)
print('FICHIERS P', [(p.name, p.stat().st_size) for p in _pfolder.iterdir()])

print('DOSSIER PARTAGE', [(p.name, p.is_dir()) for p in ROOT.parent.iterdir()], flush=True)
print('DOSSIERS MON DRIVE', [p.name for p in Path('/content/drive/MyDrive').iterdir() if p.is_dir()], flush=True)
_copies = []
for _base in {ROOT.parent.resolve(), Path('/content/drive/MyDrive').resolve()}:
    for _directory, _dirs, _files in os.walk(_base):
        _dirs[:] = [n for n in _dirs if n not in {'.git', '__pycache__', 'cache', 'resources', 'tokenizer', 'encoder_config'} and not n.startswith(('C_', 'D_', 'E_', 'A_', 'B_'))]
        for _name in _files:
            if _name in {'P_weights.pt', 'P_weights.pt.zip'} or ('P_darijabert_without_both_s42' in _directory and _name.endswith(('.pt', '.zip'))):
                _candidate = Path(_directory) / _name
                _copies.append(str(_candidate))
                print('COPIE POSSIBLE', str(_candidate), _candidate.stat().st_size, flush=True)
print('RECHERCHE TERMINEE', _copies, flush=True)

